/* Chrome wordmark stencil for the title — an 8-bit grayscale coverage mask
 * (320x48), antialiased. Generated by tools/make_logo.sh (ffmpeg drawtext).
 * Kept in its own incbin (not the pack_assets-generated assets.S) so it isn't
 * clobbered when the PNG assets are repacked. */

    .section .rodata.qs_logo, "a"
    .balign 4
    .global qs_logo_mask
qs_logo_mask:
    .incbin "logo.bin"
